/// <summary>
/// MPJ_34596_TransferOrderFinalisation UI builder for auto shipment
/// </summary>
internal final class MetTransferOrderShipmentWorkbenchRouteUpdateUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField                                                 dialogFieldPrimaryRoute,dialogFieldRouteStop,dialogFieldPrimaryRouteToChange,dialogFieldRouteStopToChange;
    MetTransferOrderShipmentWorkbenchRouteUpdateContract           dataContract;

    
}

Method.Source:
    /// <summary>
    /// post build
    /// </summary>
    public void postBuild()
    {
        super();
        dataContract    = this.dataContractObject() as MetTransferOrderShipmentWorkbenchRouteUpdateContract;

        dialogFieldPrimaryRoute        = this.bindInfo().getDialogField(dataContract, methodstr(MetTransferOrderShipmentWorkbenchRouteUpdateContract,parmPrimaryRoute));
        dialogFieldPrimaryRouteToChange        = this.bindInfo().getDialogField(dataContract, methodstr(MetTransferOrderShipmentWorkbenchRouteUpdateContract,parmPrimaryRouteChange));

        dialogFieldPrimaryRouteToChange.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(MetTransferOrderShipmentWorkbenchRouteUpdateUIBuilder, primaryRouteLookup), this);

        dialogFieldRouteStop                = this.bindInfo().getDialogField(dataContract, methodstr(MetTransferOrderShipmentWorkbenchRouteUpdateContract,parmRouteStop));
        dialogFieldRouteStopToChange        = this.bindInfo().getDialogField(dataContract, methodstr(MetTransferOrderShipmentWorkbenchRouteUpdateContract,parmRouteStopChange));
     
        dialogFieldRouteStopToChange.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(MetTransferOrderShipmentWorkbenchRouteUpdateUIBuilder, routeStopLookup), this);

        dialogFieldPrimaryRoute.enabled(false);
        dialogFieldRouteStop.enabled(false);
    }

    /// <summary>
    /// primary route lookup
    /// </summary>
    /// <param name = "_ctrl">dialog control</param>
    public void primaryRouteLookup(FormStringControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(METInventTransferTableExt), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(METInventTransferTableExt));

      
        sysTableLookup.addLookupfield(fieldNum(MetTransferShipmentTable, Route));
        queryBuildDataSource.addSortField(fieldnum(MetTransferShipmentTable, Route));
        queryBuildDataSource.addOrderByField(fieldnum(MetTransferShipmentTable, Route));
        queryBuildDataSource.orderMode(OrderMode::GroupBy);

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    ///  route stop lookup
    /// </summary>
    /// <param name = "_ctrl">dialog control</param>
    public void routeStopLookup(FormStringControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(METInventTransferTableExt), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(METInventTransferTableExt));

      
        sysTableLookup.addLookupfield(fieldNum(MetTransferShipmentTable, RouteStopNum));
        queryBuildDataSource.addSortField(fieldnum(MetTransferShipmentTable, RouteStopNum));
        queryBuildDataSource.addOrderByField(fieldnum(MetTransferShipmentTable, RouteStopNum));
        queryBuildDataSource.orderMode(OrderMode::GroupBy);

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
